import { useId, type CSSProperties } from 'react'

/**
 * The SlidesDone mark: a white slide (a heading bar and two text lines) on a cobalt tile, with a yellow "done" check badge on its corner
 * (brand colours from tokens.css: cobalt #0b3dd0, yellow #ffdf00, orange #ff5722). Pure SVG: crisp at any size and it needs no font.
 * Static copies for favicons/social are generated by e2e/make-brand-assets.mjs into apps/web/public (see docs/BRAND.md).
 */
export function LogoMark({ size = 32, title = 'SlidesDone', style, rounded = true }: { size?: number; title?: string | null; style?: CSSProperties; rounded?: boolean }) {
  const gid = useId() // gradient ids must be unique per instance on a page
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width={size} height={size} role={title ? 'img' : undefined} aria-label={title ?? undefined} aria-hidden={title ? undefined : true} style={{ display: 'block', flexShrink: 0, ...style }}>
      <defs>
        <linearGradient id={gid} x1="8" y1="2" x2="58" y2="64" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#2F63F5" />
          <stop offset="0.55" stopColor="#0B3DD0" />
          <stop offset="1" stopColor="#082A9A" />
        </linearGradient>
      </defs>
      <rect width="64" height="64" rx={rounded ? 16 : 0} fill={`url(#${gid})`} />
      <rect x="10" y="14" width="39" height="28" rx="5.5" fill="#fff" />
      <rect x="16" y="20.5" width="17" height="4.6" rx="2.3" fill="#0B3DD0" />
      <rect x="16" y="29" width="27" height="3.3" rx="1.65" fill="#C9D5FA" />
      <rect x="16" y="34.6" width="15" height="3.3" rx="1.65" fill="#C9D5FA" />
      <circle cx="46.5" cy="44.5" r="13.5" fill="#FFDF00" stroke="#0B3DD0" strokeWidth="3.5" />
      <path d="M40 44.8l4.8 4.8L53.4 39.6" fill="none" stroke="#0B3DD0" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

/**
 * Mark + wordmark. The lettering is "gradient flow": a light "Slides" (the work) flowing into a bold "Done" that shifts from cobalt to
 * orange (the finished deck) — brand colours only (cobalt #0b3dd0 → orange #ff5722). Sora 300 + 800.
 * `tone="dark"` is for dark backgrounds (white "Slides", lighter cobalt). Size = height of the mark in px.
 */
export function Logo({ size = 32, tone = 'light', wordmark = true, style }: { size?: number; tone?: 'light' | 'dark'; wordmark?: boolean; style?: CSSProperties }) {
  const dark = tone === 'dark'
  const from = dark ? '#6C8FFF' : '#0B3DD0'
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: size * 0.28, ...style }}>
      <LogoMark size={size} title={wordmark ? null : 'SlidesDone'} />
      {wordmark && (
        <span aria-label="SlidesDone" style={{ fontFamily: "var(--font-logo, 'Sora', system-ui, sans-serif)", fontSize: size * 0.74, letterSpacing: '-0.03em', lineHeight: 1, whiteSpace: 'nowrap', color: dark ? '#fff' : 'var(--color-text-primary, #181b25)' }}>
          <span aria-hidden style={{ fontWeight: 300 }}>Slides</span>
          <span aria-hidden style={{ fontWeight: 800, color: from, backgroundImage: `linear-gradient(90deg, ${from} 0%, ${from} 35%, #FF5722 100%)`, WebkitBackgroundClip: 'text', backgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Done</span>
        </span>
      )}
    </span>
  )
}
